INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v197', 11, 0, 'Report to Vreema.', 'DAT string table 0x25008b03 (questlinf3_uncharneledgolem.stt) key 0x3c699fdd: phase 11, after the last kill', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v197', 12, 1, 'Vreema said: "Geraine’s Uncharneled Golems are terrifying creatures made of dead gristle and bone. They’ve continued to guard their lord’s empty tomb down through the ages, unknowing that they’ve long survived their purpose. The golems have turned on our mining crews, not understanding that our miners bear no evil intent towards Geraine. We’ll have to clear them out once and for all. Smash 10 Uncharneled Golems, and I will reward you in the name of the Brotherhood of Shapers."', 'DAT string table 0x25008b03 (questlinf3_uncharneledgolem.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'vault');
