INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v203', 11, 0, 'Return to Sumalar.', 'DAT string table 0x25008aed (questikb3_surrogatespawn.stt) key 0x80882929: phase 11, after the last kill', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v203', 12, 1, 'Sumalar said: "\Perhaps the greatest danger to our Naderu are posed by the Surrogate Spawn, which are a mightier foe than either the Servitors or the Puppets. If they are not contained, I cannot predict the effect it will have on our precious friends. I must ask you to kill 10 Surrogate Spawn."', 'DAT string table 0x25008aed (questikb3_surrogatespawn.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'vault');
