INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v207', 11, 0, 'Return to Sister Nell Palnos.', 'DAT string table 0x25008af1 (questike1_ulusclavus.stt) key 0x77269301: phase 11, after the last kill', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v207', 12, 1, 'Sister Nell Palnos said: "The Shadow Kingdoms commissioned my brotherhood for a shipment of arms and weapons to provision their Knorr Expeditionary Force. I must have the resources to craft these items, but my mining crews are being threatened at every turn. We’ve identified a particularly rich deposit of iron ore in the Ariaki River Valley, but the Sclavus Lords who dwell there keep driving my miners out. We''ll have to "persuade" them to see things our way. Eliminate 10 Ulu Sclavus, and I’ll do my best to reward you."', 'DAT string table 0x25008af1 (questike1_ulusclavus.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v208', 1, 0, '10 Faisi Sclavus', 'DAT string table 0x25008af2 (questike2_faisisclavus.stt) key 0x314fd197: phase 1 shows the kills left (the DAT''s numbered phase lines count down, as Legions'' QuestGGWNightmare1-6 phases do)', 'vault');
