INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v209', 11, 0, 'Return to Baltor Vultu.', 'DAT string table 0x25008af3 (questikf_marsharmoredillo.stt) key 0x9342d197: phase 11, after the last kill', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v209', 12, 1, 'Baltor Vultu said: "The Marsh Armoredillos of this region have suddenly acquired a new taste for the watercresses and other riverine plants that grow in the estruaries around Ikeras. Normally we''d be pleased that they''ve turned their culinary focus from hapless adventurers to more vegitarian delights. However, now our ecologists warn that the defoliation around the riverbanks may lead to erosion and massive mudslides. Ikeras may be in danger from this unexpected threat. We’ll have to thin the Armoredillos out before they literally eat us out of house and home."', 'DAT string table 0x25008af3 (questikf_marsharmoredillo.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'vault');
